import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import styles from './HomePage.module.css';

const HomePage = () => (
  <motion.section className={styles.hero} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1 }}>
    <div className={styles.content}>
      <motion.h1 initial={{ y: 30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.2, duration: 0.8 }}>
        Искусство движения
      </motion.h1>
      <motion.p initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.5, duration: 0.8 }}>
        Эксклюзивные автомобили для тех, кто ценит совершенство
      </motion.p>
      <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: 0.8, duration: 0.5 }}>
        <Link to="/catalog" className={styles.cta}>Открыть каталог</Link>
      </motion.div>
    </div>
    <div className={styles.overlay} />
  </motion.section>
);

export default HomePage;
